package com.primehr.evidence.domain;import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import java.time.Instant;import java.util.Objects;
@Entity@Table(name="evidence_finding",uniqueConstraints=@UniqueConstraint(name="uk_evidence_finding_revision",columnNames={"agency_id","assessment_case_id","requirement_id","finding_revision"}))public class EvidenceFinding extends RspAuditedEntity{public enum Outcome{MET,PARTIALLY_MET,NOT_MET,NOT_APPLICABLE,NEEDS_REVIEW}@Column(name="assessment_case_id",nullable=false,length=36)private String assessmentCaseId;@Column(name="requirement_id",nullable=false,length=36)private String requirementId;@Column(name="requirement_code",nullable=false,length=80)private String requirementCode;@Column(name="submission_revision",nullable=false)private int submissionRevision;@Column(name="finding_revision",nullable=false)private int findingRevision;@Column(name="supersedes_id",length=36)private String supersedesId;@Column(name="current_record",nullable=false)private boolean currentRecord;@Enumerated(EnumType.STRING)@Column(nullable=false,length=30)private Outcome outcome;@Column(nullable=false,length=4000)private String rationale;@Column(name="not_applicable_authority",length=1000)private String notApplicableAuthority;@Column(name="decided_by",nullable=false,length=100)private String decidedBy;@Column(name="decided_at",nullable=false)private Instant decidedAt;protected EvidenceFinding(){}public EvidenceFinding(String a,String c,String req,String code,int submission,int revision,String supersedes,Outcome outcome,String rationale,String authority,String actor,Instant at){super(a);assessmentCaseId=requiredText(c,"assessmentCaseId");requirementId=requiredText(req,"requirementId");requirementCode=requiredText(code,"requirementCode");if(submission<1||revision<1)throw new IllegalArgumentException("Finding revisions must be positive");submissionRevision=submission;findingRevision=revision;supersedesId=optionalText(supersedes);this.outcome=Objects.requireNonNull(outcome);this.rationale=requiredText(rationale,"rationale");notApplicableAuthority=optionalText(authority);if(outcome==Outcome.NOT_APPLICABLE&&notApplicableAuthority==null)throw new IllegalArgumentException("Not applicable requires authority and reason");currentRecord=true;decidedBy=requiredText(actor,"actor");decidedAt=at;}public void supersede(){currentRecord=false;}public String getAssessmentCaseId(){return assessmentCaseId;}public String getRequirementId(){return requirementId;}public String getRequirementCode(){return requirementCode;}public int getSubmissionRevision(){return submissionRevision;}public int getFindingRevision(){return findingRevision;}public String getSupersedesId(){return supersedesId;}public boolean isCurrentRecord(){return currentRecord;}public Outcome getOutcome(){return outcome;}public String getRationale(){return rationale;}public String getNotApplicableAuthority(){return notApplicableAuthority;}public String getDecidedBy(){return decidedBy;}public Instant getDecidedAt(){return decidedAt;}}
